    const jsonData = pm.response.json();
    pm.expect(jsonData.name).to.eql("Test habit via Postman");
});

pm.test("New habit has an id", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("id");
});

